<script>
var DEFAULT_STAT = {
  "日期": "", "星期": "", "时间": "",
  "玩家": { "当前位置": "", "飞机杯当前绑定": "无", "飞机杯定位": "未知",
            "体力": 100, "性欲": 30, "勃起度": 0, "累计射精次数": 0 },
  "女性角色": {}, "男性角色": {}
};

var qiuOpenCards = {};

function safe(v, def) { return (v === undefined || v === null || v === '') ? (def || '—') : v; }
function safeNum(v, def) { var n = Number(v); return isNaN(n) ? (def || 0) : n; }

function deepMergeStat(target, source) {
  if (source === null || source === undefined) return target;
  if (typeof source !== 'object' || Array.isArray(source)) return source;
  if (typeof target !== 'object' || target === null) target = {};
  for (var k in source) {
    if (!source.hasOwnProperty(k)) continue;
    if (typeof source[k] === 'object' && source[k] !== null && !Array.isArray(source[k])) {
      target[k] = deepMergeStat(target[k] || {}, source[k]);
    } else {
      target[k] = source[k];
    }
  }
  return target;
}

function readStat() {
  var stat = JSON.parse(JSON.stringify(DEFAULT_STAT));

  // 优先级1: MVU API（实时数据，额外模型更新后的最新值）
  try {
    if (typeof Mvu !== 'undefined' && Mvu.getMvuData) {
      var mvuStat = Mvu.getMvuData();
      if (mvuStat) stat = deepMergeStat(stat, mvuStat);
    }
  } catch(e) {}

  // 优先级2: ST getVariables（chat 级变量）
  try {
    if (typeof SillyTavern !== 'undefined' && typeof getVariables === 'function') {
      var vars = getVariables({ type: 'chat' });
      if (vars && vars.stat_data) stat = deepMergeStat(stat, vars.stat_data);
    }
  } catch(e) {}

  // 优先级3: embed 块（主模型消息内嵌的快照，可能滞后）
  try {
    var embed = document.getElementById('mvu-stat-embed');
    if (embed && embed.textContent && embed.textContent.trim()) {
      var raw = embed.textContent.trim();
      if (raw.indexOf('{') === 0 || raw.indexOf('[') === 0) {
        var parsed = JSON.parse(raw);
        stat = deepMergeStat(stat, parsed);
      }
    }
  } catch(e) {}

  return stat;
}

function bar(value, max, cls) {
  var v = safeNum(value, 0);
  var pct = max > 0 ? Math.min(100, (v / max) * 100) : 0;
  return '<div class="qiu-bar-container"><div class="qiu-bar-track"><div class="qiu-bar-fill ' + (cls||'') + '" style="width:' + pct + '%"></div></div></div>';
}

function progressRow(name, value, max, phase, cls) {
  return '<div class="qiu-bar-container">' +
    '<div class="qiu-bar-top"><span class="qiu-progress-name">' + name + '</span><span>' + safeNum(value,0) + '/' + max + (phase ? ' · ' + phase : '') + '</span></div>' +
    '<div class="qiu-bar-track"><div class="qiu-bar-fill ' + (cls||'') + '" style="width:' + (max > 0 ? Math.min(100, (safeNum(value,0)/max)*100) : 0) + '%"></div></div>' +
  '</div>';
}

function phaseName(val, thresholds) {
  var v = safeNum(val, 0);
  for (var i = 0; i < thresholds.length; i++) {
    if (v <= thresholds[i].max) return thresholds[i].name;
  }
  return thresholds[thresholds.length-1].name;
}

function renderPlayer(stat) {
  var p = stat.玩家 || {};
  var html = '<div class="qiu-env-box" style="margin-bottom:6px;">';
  html += '<div class="qiu-data-row"><span class="qiu-label">体力</span><span class="qiu-val ' + (safeNum(p.体力,100) < 30 ? 'warn' : 'success') + '">' + safeNum(p.体力,100) + '/100</span></div>';
  html += bar(p.体力, 100, safeNum(p.体力,100) < 30 ? 'warn' : 'success');
  html += '<div class="qiu-data-row"><span class="qiu-label">性欲</span><span class="qiu-val ' + (safeNum(p.性欲,30) > 70 ? 'danger' : 'info') + '">' + safeNum(p.性欲,30) + '/100</span></div>';
  html += bar(p.性欲, 100, safeNum(p.性欲,30) > 70 ? 'danger' : 'info');
  html += '<div class="qiu-data-row"><span class="qiu-label">勃起度</span><span class="qiu-val ' + (safeNum(p.勃起度,0) > 70 ? 'danger' : '') + '">' + safeNum(p.勃起度,0) + '/100</span></div>';
  html += bar(p.勃起度, 100);
  html += '<div class="qiu-data-row"><span class="qiu-label">累计射精</span><span class="qiu-val">' + safeNum(p.累计射精次数,0) + ' 次</span></div>';
  html += '</div>';
  return html;
}

function renderFemale(name, c, isBind) {
  var cardCls = 'qiu-char-card';
  if (isBind || c.被绑定状态) cardCls += ' is-bind';
  if (c.终局) cardCls += ' is-finale';

  var portrait = name.charAt(0) || '?';
  var tags = '';
  if (c.身份) tags += '<span class="qiu-tag">' + safe(c.身份) + '</span>';
  if (c.已激活) tags += '<span class="qiu-tag">已激活</span>';
  if (isBind || c.被绑定状态) tags += '<span class="qiu-tag" style="background:rgba(240,98,146,0.3);color:#fff;">绑定中</span>';
  if (c.终局) tags += '<span class="qiu-tag" style="background:rgba(216,27,96,0.3);color:#fff;">终局</span>';

  var html = '<div class="' + cardCls + '">';
  html += '<button class="qiu-card-header" type="button">';
  html += '<div class="qiu-card-head-left">';
  html += '<div class="qiu-char-portrait' + (c.终局 ? ' finale' : '') + '">' + portrait + '</div>';
  html += '<div class="qiu-card-head-info">';
  html += '<div class="qiu-char-name">' + safe(name) + '</div>';
  html += '<div class="qiu-char-tags">' + tags + '</div>';
  html += '</div></div>';
  html += '<svg class="qiu-chevron" viewBox="0 0 24 24"><path d="M7 10l5 5 5-5z"/></svg>';
  html += '</button>';
  html += '<div class="qiu-card-body">';

  // 核心数值
  html += '<div class="qiu-subsection"><div class="qiu-subsection-title">核心数值</div>';
  var cjPhase = phaseName(c.察觉度, [{max:50,name:'完全未知'},{max:100,name:'局部虚影'},{max:150,name:'整体轮廓'},{max:151,name:'完全显现'}]);
  html += progressRow('察觉度', c.察觉度, 151, cjPhase, c.察觉度 >= 151 ? 'danger' : 'info');
  var qxPhase = phaseName(c.倾心度, [{max:50,name:'抗拒'},{max:100,name:'动摇'},{max:150,name:'接受'},{max:200,name:'迎合'}]);
  html += progressRow('倾心度', c.倾心度, 200, qxPhase, c.倾心度 >= 151 ? 'success' : '');
  var jxPhase = phaseName(c.具现度, [{max:50,name:'杯子'},{max:100,name:'臀部'},{max:150,name:'半身'},{max:200,name:'全身'}]);
  html += progressRow('具现度', c.具现度, 200, jxPhase, 'warn');
  html += '</div>';

  // 服装状态
