  if (body.胸部) {
    html += '<div class="qiu-data-row"><span class="qiu-label">胸部</span><span class="qiu-val ' + (body.胸部.状态 === '红肿' ? 'danger' : body.胸部.状态 === '敏感' ? 'warn' : '') + '">' + safe(body.胸部.状态) + ' / ' + safe(body.胸部.乳头) + '</span></div>';
