  html += progressRow('恐惧感', psy.恐惧感, 100, '', 'danger');
  html += progressRow('欲望度', psy.欲望度, 100, '', 'warn');
  html += progressRow('期待感', psy.期待感, 100, '', 'success');
  html += progressRow('心理防线', psy.心理防线, 100, '', safeNum(psy.心理防线,100) < 30 ? 'danger' : 'success');
  html += '<div class="qiu-data-row"><span class="qiu-label">精神</span><span class="qiu-val ' + (psy.精神状态 === '昏迷' || psy.精神状态 === '失神' ? 'danger' : psy.精神状态 === '虚脱' ? 'warn' : '') + '">' + safe(psy.精神状态, '清醒') + '</span></div>';
  html += '</div>';

  // 实时状态
  var rt = c.实时状态 || {};
  html += '<div class="qiu-subsection"><div class="qiu-subsection-title">实时状态</div>';
  html += '<div class="qiu-data-row"><span class="qiu-label">姿势</span><span class="qiu-val">' + safe(rt.当前姿势) + '</span></div>';
  html += '<div class="qiu-data-row"><span class="qiu-label">动作</span><span class="qiu-val">' + safe(rt.当前动作) + '</span></div>';
  html += '<div class="qiu-data-row"><span class="qiu-label">场景</span><span class="qiu-val">' + safe(rt.当前场景) + '</span></div>';
  html += '<div class="qiu-data-row"><span class="qiu-label">进度</span><span class="qiu-val ' + (rt.互动进度 === '高潮中' ? 'danger' : rt.互动进度 === '进行中' ? 'warn' : '') + '">' + safe(rt.互动进度) + '</span></div>';
  if (rt.当前刺激部位 && rt.当前刺激部位 !== '无') {
    html += '<div class="qiu-data-row"><span class="qiu-label">刺激部位</span><span class="qiu-val warn">' + safe(rt.当前刺激部位) + '</span></div>';
