  html += '</div>';

  // 互动过程
  var ip = c.互动过程 || {};
  html += '<div class="qiu-subsection"><div class="qiu-subsection-title">本轮互动</div>';
  html += '<div class="qiu-data-row"><span class="qiu-label">高潮次数</span><span class="qiu-val ' + (safeNum(ip.本轮高潮次数,0) > 0 ? 'danger' : '') + '">' + safeNum(ip.本轮高潮次数,0) + '</span></div>';
  html += '<div class="qiu-data-row"><span class="qiu-label">时长</span><span class="qiu-val">' + safe(ip.本轮互动时长, '0分钟') + '</span></div>';
