  html += progressRow('心理冲击', ip.本轮心理冲击, 100, '', 'danger');
  if (safeNum(ip.高潮强度,0) > 0) {
    html += progressRow('高潮强度', ip.高潮强度, 100, '', 'danger');
  }
  if (safeNum(ip.射精量,0) > 0) {
    html += progressRow('射精量', ip.射精量, 100, '', 'warn');
  }
  if (ip.敏感点反应) {
    html += '<div class="qiu-text-box">敏感点：' + safe(ip.敏感点反应) + '</div>';
  }
  html += '</div>';

  // 长期跟踪
  html += '<div class="qiu-subsection"><div class="qiu-subsection-title">长期跟踪</div>';
  html += '<div class="qiu-data-row"><span class="qiu-label">总互动</span><span class="qiu-val">' + safeNum(c.总互动次数,0) + ' 次</span></div>';
  html += '<div class="qiu-data-row"><span class="qiu-label">总高潮</span><span class="qiu-val">' + safeNum(c.高潮次数,0) + ' 次</span></div>';
  html += '<div class="qiu-data-row"><span class="qiu-label">总内射</span><span class="qiu-val ' + (safeNum(c.总内射次数,0) > 0 ? 'danger' : '') + '">' + safeNum(c.总内射次数,0) + ' 次</span></div>';
  html += '<div class="qiu-data-row"><span class="qiu-label">总潮吹</span><span class="qiu-val">' + safeNum(c.总潮吹次数,0) + ' 次</span></div>';
  html += '<div class="qiu-data-row"><span class="qiu-label">关系阶段</span><span class="qiu-val info">' + safe(c.关系阶段, '未接触') + '</span></div>';
  if (c.首次互动日期) {
    html += '<div class="qiu-data-row"><span class="qiu-label">首次互动</span><span class="qiu-val">' + safe(c.首次互动日期) + '</span></div>';
  }
  html += '</div>';

  // 总结
  var sum = c.总结 || {};
