    }
    if (sum.重要事件标记 && sum.重要事件标记.length > 0) {
      html += '<div class="qiu-event-list"><div style="font-weight:bold;margin-bottom:4px;">重要事件</div>';
      for (var i = 0; i < sum.重要事件标记.length; i++) {
        html += '<div class="qiu-event-item">• ' + sum.重要事件标记[i] + '</div>';
      }
      html += '</div>';
    }
    html += '</div>';
  }

  // 心情/心声/状态
  if (c.心情 && c.心情 !== '—') {
