}

function renderMale(name, c) {
  var portrait = (name.charAt(0) || '?');
  var html = '<div class="qiu-char-card">';
  html += '<button class="qiu-card-header" type="button">';
  html += '<div class="qiu-card-head-left">';
  html += '<div class="qiu-char-portrait male">' + portrait + '</div>';
  html += '<div class="qiu-card-head-info">';
  html += '<div class="qiu-char-name" style="color:var(--q-text-muted);">' + safe(name) + '</div>';
  var cloth = c.服装 || {};
  html += '<div class="qiu-char-tags">';
  if (c.是否在场) html += '<span class="qiu-tag">在场</span>';
  if (cloth.整体着装状态 && cloth.整体着装状态 !== '未知') html += '<span class="qiu-tag">' + safe(cloth.整体着装状态) + '</span>';
  html += '</div>';
  html += '</div></div>';
  html += '<svg class="qiu-chevron" viewBox="0 0 24 24"><path d="M7 10l5 5 5-5z"/></svg>';
  html += '</button>';
  html += '<div class="qiu-card-body">';
  html += '<div class="qiu-data-row"><span class="qiu-label">位置</span><span class="qiu-val">' + safe(c.当前位置) + '</span></div>';
  if (cloth.上身) html += '<div class="qiu-data-row"><span class="qiu-label">上身</span><span class="qiu-val">' + safe(cloth.上身) + '</span></div>';
  if (cloth.裤子) html += '<div class="qiu-data-row"><span class="qiu-label">裤子</span><span class="qiu-val">' + safe(cloth.裤子) + '</span></div>';
  if (c.心情 && c.心情 !== '—') html += '<div class="qiu-text-box mood-box">心情：' + safe(c.心情) + '</div>';
  if (c.当前状态) html += '<div class="qiu-text-box status-box">状态：' + safe(c.当前状态) + '</div>';
  html += '</div></div>';
  return html;
}

function bindCardToggle() {
  var headers = document.querySelectorAll('.qiu-card-header');
  for (var i = 0; i < headers.length; i++) {
    headers[i].onclick = function() {
      var card = this.parentNode;
      if (card && card.className.indexOf('qiu-char-card') !== -1) {
        var nameEl = this.querySelector('.qiu-char-name');
        var cardName = nameEl ? nameEl.textContent : '';
        if (card.className.indexOf('is-open') !== -1) {
          card.className = card.className.replace(/\s*is-open\s*/, ' ').trim();
          if (cardName) delete qiuOpenCards[cardName];
        } else {
          card.className = (card.className + ' is-open').trim();
          if (cardName) qiuOpenCards[cardName] = true;
        }
      }
    };
  }
}

function restoreOpenState() {
  var cards = document.querySelectorAll('.qiu-char-card');
  for (var i = 0; i < cards.length; i++) {
    var nameEl = cards[i].querySelector('.qiu-char-name');
    if (!nameEl) continue;
    var name = nameEl.textContent;
    if (qiuOpenCards[name]) {
      cards[i].className = (cards[i].className + ' is-open').trim();
    }
  }
}

function populateCharacterData() {
  var stat = readStat();

  document.getElementById('qiu-datetime').textContent = safe(stat.日期) + ' ' + safe(stat.时间);
  document.getElementById('qiu-weekday').textContent = safe(stat.星期);
  document.getElementById('qiu-location').textContent = safe(stat.玩家 && stat.玩家.当前位置);
  document.getElementById('qiu-cup-bind').textContent = safe(stat.玩家 && stat.玩家.飞机杯当前绑定, '无');
  document.getElementById('qiu-cup-loc').textContent = safe(stat.玩家 && stat.玩家.飞机杯定位, '未知');

  var bindBox = document.getElementById('qiu-cup-bind-box');
  var bindName = stat.玩家 && stat.玩家.飞机杯当前绑定;
  if (bindName && bindName !== '无') {
    bindBox.className = 'qiu-env-box bind-active';
  } else {
    bindBox.className = 'qiu-env-box';
  }

  var playerBox = document.getElementById('qiu-player-box');
  playerBox.innerHTML = renderPlayer(stat);

  var femaleContainer = document.getElementById('qiu-female-chars');
  var females = stat.女性角色 || {};
  var femaleNames = Object.keys(females);
  if (femaleNames.length === 0) {
    femaleContainer.innerHTML = '<div class="qiu-empty-hint">暂无已追踪女性角色</div>';
  } else {
    var fhtml = '';
    var bindNameLower = bindName;
    for (var i = 0; i < femaleNames.length; i++) {
      var n = femaleNames[i];
      fhtml += renderFemale(n, females[n], n === bindNameLower);
    }
    femaleContainer.innerHTML = fhtml;
  }

  var maleContainer = document.getElementById('qiu-male-chars');
  var males = stat.男性角色 || {};
  var maleNames = Object.keys(males);
  if (maleNames.length === 0) {
    maleContainer.innerHTML = '<div class="qiu-empty-hint">暂无男性角色</div>';
  } else {
    var mhtml = '';
    for (var j = 0; j < maleNames.length; j++) {
      mhtml += renderMale(maleNames[j], males[maleNames[j]]);
    }
    maleContainer.innerHTML = mhtml;
  }

  bindCardToggle();
  restoreOpenState();
}

function autoRefresh() {
  setTimeout(function() { populateCharacterData(); }, 800);
}

function setupEventListeners() {
  try {
    var eventSource = null;
    var eventTypes = null;
    if (typeof window.parent !== 'undefined' && window.parent.eventSource) {
      eventSource = window.parent.eventSource;
      eventTypes = window.parent.event_types;
    } else if (typeof SillyTavern !== 'undefined' && SillyTavern.eventSource) {
      eventSource = SillyTavern.eventSource;
      eventTypes = SillyTavern.event_types;
    }
    if (eventSource) {
      if (eventTypes && eventTypes.GENERATION_ENDED) {
        eventSource.on(eventTypes.GENERATION_ENDED, autoRefresh);
      }
      if (eventTypes && eventTypes.MESSAGE_EDITED) {
        eventSource.on(eventTypes.MESSAGE_EDITED, autoRefresh);
      }
      eventSource.on('mag_variable_update_ended', autoRefresh);
    }
  } catch(e) {}
}

function init() {
  populateCharacterData();
  setupEventListeners();
  setInterval(function() { populateCharacterData(); }, 10000);
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', init);
} else {
  init();
}
</script>
</body>
</html>
