// 飞机杯 - MVU 变量结构注册脚本
// 作为 Tavern Helper 脚本加载到酒馆助手扩展中
// 作用：将 Schema 注册到 MVU 插件，启用额外模型解析 + Zod 校验
// 部署：在酒馆助手扩展中新增脚本，将本文件内容粘贴进去，启用即可

import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

// Schema 定义（与 source/mvu/schema.js 同步，此处内联以避免运行时路径解析问题）
const Schema = z.object({
  日期: z.coerce.string().prefault(''),
  星期: z.coerce.string().prefault(''),
  时间: z.coerce.string().prefault(''),

  玩家: z.object({
    当前位置: z.coerce.string().prefault(''),
    飞机杯当前绑定: z.coerce.string().prefault('无'),
    飞机杯定位: z.coerce.string().prefault('未知'),
  }).prefault({}),

  女性角色: z.record(
    z.string().describe('女性角色姓名'),
    z.object({
      当前位置: z.coerce.string().prefault('未知'),
      性别: z.literal('女').prefault('女'),
      身份: z.coerce.string().prefault(''),
      已激活: z.boolean().prefault(false),
      察觉度: z.coerce.number().transform(v => _.clamp(v, 0, 151)).prefault(0),
      倾心度: z.coerce.number().transform(v => _.clamp(v, 0, 200)).prefault(0),
      具现度: z.coerce.number().transform(v => _.clamp(v, 0, 200)).prefault(0),
      终局: z.boolean().prefault(false),
      终局倾心度: z.coerce.number().transform(v => _.clamp(v, 0, 200)).prefault(0),
      高潮次数: z.coerce.number().prefault(0),
      连续正面日数: z.coerce.number().prefault(0),
      心情: z.coerce.string().prefault('—'),
      心声: z.coerce.string().prefault(''),
      当前状态: z.coerce.string().prefault(''),
      是否在场: z.boolean().prefault(false),
    }).prefault({})
  ).prefault({}),

  男性角色: z.record(
    z.string().describe('男性角色姓名'),
    z.object({
      当前位置: z.coerce.string().prefault('未知'),
      心情: z.coerce.string().prefault('—'),
      心声: z.coerce.string().prefault(''),
      当前状态: z.coerce.string().prefault(''),
      是否在场: z.boolean().prefault(false),
    }).prefault({})
  ).prefault({}),
});

$(() => {
  registerMvuSchema(Schema);
});

